private void pop(final String descriptor){
    // Implementation of the pop method based on the descriptor
    int descriptorIndex = 0;
    if (descriptor.charAt(0) == '(') { // it's a method descriptor
        descriptorIndex = 1; // skip the '('
        while (descriptor.charAt(descriptorIndex) != ')') {
            descriptorIndex = popType(descriptor, descriptorIndex);
        }
        descriptorIndex++; // skip the ')'
    }
    popType(descriptor, descriptorIndex);
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'V': // void
            return index + 1;
        case 'Z': // boolean
        case 'C': // char
        case 'B': // byte
        case 'S': // short
        case 'I': // int
            return index + 1;
        case 'F': // float
            return index + 1;
        case 'J': // long
        case 'D': // double
            return index + 1;
        case 'L': // object
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            return index + 1;
        case '[': // array
            return popType(descriptor, index + 1);
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

