GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty() || graph == null) {
        return null;
    }

    GraphPath<V, E> path = new DefaultGraphPath<>();
    if (tour.size() == 1) {
        E edge = tour.iterator().next();
        path.add(edge);
        V source = graph.getEdgeSource(edge);
        path.add(source);
        path.add(graph.getEdgeTarget(edge));
        return path;
    }

    V startVertex = null;
    // Find a starting vertex with odd degree
    for (V vertex : graph.vertexSet()) {
        int degree = 0;
        for (E edge : tour) {
            if (graph.getEdgeSource(edge).equals(vertex) || graph.getEdgeTarget(edge).equals(vertex)) {
                degree++;
            }
        }
        if (degree % 2 != 0) {
            startVertex = vertex;
            break;
        }
    }
    if (startVertex == null) {
        // If no vertex with odd degree is found, start with any vertex that has an edge in the tour
        for (E edge : tour) {
            startVertex = graph.getEdgeSource(edge);
            break;
        }
    }

    Deque<E> edgeStack = new ArrayDeque<>();
    Deque<V> vertexStack = new ArrayDeque<>();
    vertexStack.push(startVertex);

    while (!vertexStack.isEmpty()) {
        V currentVertex = vertexStack.peek();
        boolean hasUnvisitedEdges = false;

        for (E edge : tour) {
            V u = graph.getEdgeSource(edge);
            V v = graph.getEdgeTarget(edge);
            if ((u.equals(currentVertex) || v.equals(currentVertex)) && !path.contains(edge)) {
                hasUnvisitedEdges = true;
                edgeStack.push(edge);
                vertexStack.push(u.equals(currentVertex) ? v : u);
                tour.remove(edge); // Mark the edge as visited by removing it from the set
                break;
            }
        }

        if (!hasUnvisitedEdges) {
            path.add(vertexStack.pop(), edgeStack.pop());
        }
    }

    return path;
}

